<?php require __DIR__.'/../config/bootstrap.php';if(current_user()&&current_user()['role']!=='user')redirect('dashboard.php');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$st=db()->prepare("SELECT * FROM users WHERE email=? AND role IN('super_admin','admin','editor','author') AND status='active'");$st->execute([trim($_POST['email'])]);$u=$st->fetch();if($u&&password_verify($_POST['password'],$u['password_hash'])){login_user($u);redirect('dashboard.php');}flash('error','Invalid admin credentials.');}?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/css/app.css"><title>Admin Login</title></head><body><main class="wrap" style="max-width:480px;padding-top:12vh"><h1>PlayGramBlog Admin</h1><?php show_flash();?><form class="form" method="post"><?=csrf_field()?><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><button>Sign in</button></form></main></body></html>